// ── Validation helpers (mirrors the pipeline's honest-data rules) ───────

export const HACKATHON_MODES = ["online", "offline", "hybrid"];
export const MODE_LABEL = { online: "线上", offline: "线下", hybrid: "线上+线下" };

/** Validate the ISO date strings this dataset promises. Returns the value or null. */
export function normDateOrNull(v) {
  if (typeof v !== "string") return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v.trim());
  if (!m) return null;
  const [, y, mo, d] = m.map(Number);
  const dt = new Date(y, mo - 1, d);
  if (dt.getFullYear() !== y || dt.getMonth() !== mo - 1 || dt.getDate() !== d) return null;
  return v.trim();
}

/**
 * One validated record: only fields that pass shape checks survive; an
 * invalid record is DROPPED (never guessed into shape). The UI renders
 * "待定" for every null — honesty over completeness.
 */
export function normalizeHackathon(a) {
  if (!a || typeof a !== "object") return null;
  const id = String(a.id || "");
  const title = String(a.title || "");
  if (!id || !title) return null; // identity is required, everything else can be 待定
  const mode = HACKATHON_MODES.indexOf(a.mode) >= 0 ? a.mode : null;
  const registrationDeadline =
    typeof a.registrationDeadline === "string" && !isNaN(Date.parse(a.registrationDeadline))
      ? a.registrationDeadline
      : null;
  const demo = a.demo === true; // curated REAL data — demo only when explicitly true
  return {
    id,
    title,
    category: typeof a.category === "string" && a.category ? a.category : "hackathon",
    city: a.city == null ? null : String(a.city),
    mode,
    startDate: normDateOrNull(a.startDate),
    endDate: normDateOrNull(a.endDate),
    registrationDeadline,
    prize: a.prize == null ? null : String(a.prize),
    prizeType: a.prizeType === "cash" ? "cash" : null,
    eligibility: a.eligibility == null ? null : String(a.eligibility),
    teamSize: a.teamSize == null ? null : String(a.teamSize),
    venue: a.venue == null ? null : String(a.venue),
    address: a.address == null ? null : String(a.address),
    organizer: a.organizer == null ? null : String(a.organizer),
    description: a.description == null ? null : String(a.description),
    tags: Array.isArray(a.tags) ? a.tags.map(String) : [],
    trustScore: typeof a.trustScore === "number" ? a.trustScore : null,
    trustReasons: Array.isArray(a.trustReasons) ? a.trustReasons.map(String) : [],
    registrationUrl: typeof a.registrationUrl === "string" && a.registrationUrl ? a.registrationUrl : null,
    sourceUrl: typeof a.sourceUrl === "string" && a.sourceUrl ? a.sourceUrl : null,
    sourceName: a.sourceName == null ? null : String(a.sourceName),
    collectedAt: a.collectedAt == null ? null : String(a.collectedAt),
    demo,
  };
}

/** Validate the whole dataset; drop invalid records, keep the rest verbatim. */
export function validatedHackathons(list) {
  if (!Array.isArray(list)) return [];
  return list.map(normalizeHackathon).filter(Boolean);
}
